WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_multiple_interval'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '间隔倍数', 'kp-xingce-data-multiple-interval', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "间隔倍数"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "融合了“基期倍数”与“间隔增长率”的双重究极套娃模型。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "如果题目给你 2023年 和 2022年的各自同比增速，却问你 2021年 A 是 B 的多少倍。时间跨度为 2 年。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这种题型没有任何新知识，全靠两大硬核板块拼接："}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算分子的间隔增长率 Ra：利用 r1+r2+r1×r2 算出 A 跨越两年的整体增速。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算分母的间隔增长率 Rb：同样算出 B 跨越两年的整体增速。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "套用基期倍数公式：拿着 Ra 和 Rb，当成普通的增速，套进公式 A/B × (1+Rb)/(1+Ra)。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤与战术取舍"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[识别出间隔两年的倍数计算] --> B{剩余考试时间充足吗?}\nB -- 充足 --> C[疯狂算两遍间隔增长率]\nC --> D[再列出复杂的四则混合算式求解]\nB -- 不足5分钟 --> E[战略性放弃!]\nE --> F[随便根据今年倍数 A/B 蒙一个选项, 赶紧去做下一题]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导（如果非要算）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年A=100, B=50。A的23年和22年增速分别为10%, 20%。B的23年和22年增速为5%, 10%。求2021年A是B的几倍？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ra = 10% + 20% + 2% = 32%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Rb = 5% + 10% + 0.5% = 15.5%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "现期倍数 A/B = 100/50 = 2。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "基期倍数 = 2 × (1.155 / 1.32) ≈ 2 × 0.875 = 1.75。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "迷失在连环计算中：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "这种题目的计算链条极长，稍微算错一个中间变量（比如Ra算错了），整个答案就会偏移到命题人为你准备的错误选项上。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "对这类被称为“时间杀手”的题目，最高级的技巧就是“学会放弃”。保证在考场上能识别出它，并且能控制住自己不去死磕的冲动，你就超越了 50% 的对手。"}]}]}$$ AS jsonb), NULL, '间隔倍数的核心考点与实战推导。', category_node.id, CAST('["资料分析", "间隔倍数"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_multiple_interval", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
